```tsx
import React, { Component, ErrorInfo, ReactNode } from "react";

interface Props {
  children: ReactNode;
  fallback?: ReactNode;
  onError?: (error: Error, errorInfo: ErrorInfo) => void;
}

interface State {
  hasError: boolean;
  error: Error | null;
  errorInfo: ErrorInfo | null;
}

export class ErrorBoundary extends Component<Props, State> {
  state: State = {
    hasError: false,
    error: null,
    errorInfo: null,
  };

  static getDerivedStateFromError(error: Error): Partial<State> {
    return { hasError: true, error };
  }

  componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    this.setState({ errorInfo });

    console.error("[ErrorBoundary] Caught render error:", {
      message: error.message,
      stack: error.stack,
      componentStack: errorInfo.componentStack,
    });

    this.props.onError?.(error, errorInfo);
  }

  handleRetry = () => {
    this.setState({ hasError: false, error: null, errorInfo: null });
  };

  render() {
    if (!this.state.hasError) {
      return this.props.children;
    }

    if (this.props.fallback) {
      return this.props.fallback;
    }

    const { error, errorInfo } = this.state;

    return (
      <div role="alert" style={styles.container}>
        <h2 style={styles.title}>Something went wrong</h2>
        <p style={styles.message}>{error?.message ?? "An unexpected error occurred."}</p>
        {process.env.NODE_ENV === "development" && errorInfo?.componentStack && (
          <details style={styles.details}>
            <summary style={styles.summary}>Component stack</summary>
            <pre style={styles.stack}>{errorInfo.componentStack}</pre>
          </details>
        )}
        <button onClick={this.handleRetry} style={styles.button}>
          Try again
        </button>
      </div>
    );
  }
}

const styles: Record<string, React.CSSProperties> = {
  container: {
    display: "flex",
    flexDirection: "column",
    alignItems: "center",
    justifyContent: "center",
    padding: "2rem",
    gap: "1rem",
    fontFamily: "sans-serif",
    textAlign: "center",
  },
  title: { margin: 0, fontSize: "1.5rem", color: "#dc2626" },
  message: { margin: 0, color: "#374151", maxWidth: "480px" },
  details: {
    textAlign: "left",
    width: "100%",
    maxWidth: "640px",
    border: "1px solid #e5e7eb",
    borderRadius: "4px",
    padding: "0.5rem",
  },
  summary: { cursor: "pointer", color: "#6b7280", fontSize: "0.875rem" },
  stack: { fontSize: "0.75rem", color: "#6b7280", overflow: "auto", marginTop: "0.5rem" },
  button: {
    padding: "0.5rem 1.25rem",
    fontSize: "0.875rem",
    fontWeight: 600,
    color: "#ffffff",
    background: "#2563eb",
    border: "none",
    borderRadius: "6px",
    cursor: "pointer",
  },
};
```

**Usage:**

```tsx
// Basic — wraps children, shows built-in fallback UI
<ErrorBoundary>
  <MyComponent />
</ErrorBoundary>

// Custom fallback UI
<ErrorBoundary fallback={<p>Failed to load this section.</p>}>
  <MyComponent />
</ErrorBoundary>

// Hook into error for your logging service (Sentry, Datadog, etc.)
<ErrorBoundary onError={(err, info) => Sentry.captureException(err, { extra: info })}>
  <MyComponent />
</ErrorBoundary>
```

**Key design decisions:**

- **Class component** — required; hooks can't implement `componentDidCatch` / `getDerivedStateFromError`.
- **Retry resets state** — clears `hasError`, giving the child tree a fresh render attempt without a page reload.
- **Component stack only in dev** — the `<details>` block is gated on `NODE_ENV`, so production users never see raw stack traces.
- **`onError` prop** — lets callers wire in any external error logger without coupling the component to a specific service.

